import{_ as e,o as a,c as o,ag as i}from"./chunks/framework.CxkNbRKf.js";const n="/nada-documentation/images/captcha_options.png",c="/nada-documentation/images/create_google_captcha.png",r="/nada-documentation/images/google_recaptcha_config.png",p="/nada-documentation/images/verify_captcha.png",_=JSON.parse('{"title":"Configure Captcha","description":"","frontmatter":{},"headers":[],"relativePath":"installation-guide/configurations/captcha.md","filePath":"installation-guide/configurations/captcha.md","lastUpdated":1786379412000}'),l={name:"installation-guide/configurations/captcha.md"};function s(g,t,h,u,d,m){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="configure-captcha" tabindex="-1">Configure Captcha <a class="header-anchor" href="#configure-captcha" aria-label="Permalink to &quot;Configure Captcha&quot;">​</a></h1><p>You can use a built-in image captcha or Google Recaptcha v2.</p><h2 id="using-builtin-image-captcha" tabindex="-1">Using builtin Image Captcha <a class="header-anchor" href="#using-builtin-image-captcha" aria-label="Permalink to &quot;Using builtin Image Captcha&quot;">​</a></h2><ol><li><p>Edit the configuration file <strong>application/config/captcha.php</strong>.</p></li><li><p>Change the config option on <strong>line 12</strong> to <strong>image_captcha</strong>.</p></li></ol><p><img src="'+n+'" alt=""></p><ol start="3"><li><p>Save the file.</p></li><li><p>To test, go to the login page and click on the <strong>Register</strong> link and you should see the Recaptcha visible at the bottom of the User Registration form.</p></li></ol><h2 id="using-google-recpatcha-v2" tabindex="-1">Using Google Recpatcha v2 <a class="header-anchor" href="#using-google-recpatcha-v2" aria-label="Permalink to &quot;Using Google Recpatcha v2&quot;">​</a></h2><p>To use Google Captcha please follow the steps given below:</p><ol><li><p>To use the Google Recaptcha, you&#39;ll need to generate the public/private keys using the google recaptcha website.</p></li><li><p>Visit the Google Recaptcha website - <a href="https://www.google.com/recaptcha" target="_blank" rel="noreferrer">https://www.google.com/recaptcha</a></p></li><li><p>Login to the website, or sign up.</p></li><li><p>Once you have logged in, go to the Admin console to <strong>Register a new site</strong> or visit <a href="https://www.google.com/recaptcha/admin/create" target="_blank" rel="noreferrer">https://www.google.com/recaptcha/admin/create</a></p></li></ol><p><img src="'+c+'" alt=""></p><ul><li><p>a. Provide a Label.</p></li><li><p>b. For ReCaptcha type, choose <strong>reCaptcha v2</strong> &gt; <strong>&quot;I&#39;m not a robot&quot; Checkbox</strong> option.</p></li><li><p>c. Submit the form, which will open a confirmation page with the <strong>Site Key</strong> and <strong>Secret Key</strong>. We will need the keys to be added to the NADA configurations for ReCaptcha.</p></li></ul><ol start="5"><li><p>Edit the NADA configuration file <code>application/config/captcha.php</code>.</p></li><li><p>Change the config option on line 12 to <strong>recaptcha</strong>.</p></li><li><p>Copy <strong>Site key</strong> and <strong>Secret key</strong> from Google ReCaptcha page and inserte it on line number 51 and 52 respectively as shown in below image</p></li></ol><p><img src="'+r+'" alt=""></p><ol start="8"><li>To verify Recpatcha, visit the user registration page in NADA and verify that you can see the reCaptcha similar to the screenshot below.</li></ol><p><img src="'+p+'" alt=""></p>',15)])])}const b=e(l,[["render",s]]);export{_ as __pageData,b as default};
